/*
 * A209759  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A209760; see the Formula section.
 * https://oeis.org/A209759
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the coefficient u(r,k) from the triangle of coefficients
 *            of polynomials u(n,x) generated by u(1,x)=1, v(1,x)=1
 *            u(n,x)=x*u(n-1,x)+(x+1)*v(n-1,x) v(n,x)=x*u(n-1,x)+2x*v(n-1,x)+1
 *            (n ≥ 2) The coefficient is taken at the unique row r satisfying
 *            r(r−1)/2 < n ≤ r(r+1)/2, and at position k = n −...
 * Range:     u8 n <= 26, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* Memoization storage for rows 1..max_row.  Indices 0 are unused. */
static seq_t **u_rows = NULL;
static seq_t **v_rows = NULL;
static idx_t rows_allocated = 0;
static idx_t max_row = 0;

/* Ensure the pointer arrays can address rows up to 'need'. */
static void grow_row_arrays(idx_t need)
{
    if (need < rows_allocated)
        return;
    size_t new_cap = rows_allocated ? (size_t)rows_allocated * 2 : 64;
    while (new_cap <= (size_t)need)
        new_cap <<= 1;
    u_rows = (seq_t **)realloc(u_rows, new_cap * sizeof(seq_t *));
    v_rows = (seq_t **)realloc(v_rows, new_cap * sizeof(seq_t *));
    rows_allocated = (idx_t)new_cap;
}

/* Compute and store rows up to 'target' (inclusive). */
static void compute_rows_up_to(idx_t target)
{
    if (target <= max_row)
        return;

    for (idx_t r = max_row + 1; r <= target; ++r)
    {
        grow_row_arrays(r);

        seq_t *u_new = (seq_t *)malloc(sizeof(seq_t) * r);
        seq_t *v_new = (seq_t *)malloc(sizeof(seq_t) * r);

        if (r == 1)          /* Base row. */
        {
            u_new[0] = (seq_t)1;
            v_new[0] = (seq_t)1;
        }
        else
        {
            seq_t *u_prev = u_rows[r - 1];
            seq_t *v_prev = v_rows[r - 1];

            for (idx_t k = 0; k < r; ++k)
            {
                /* u_new[k] = a_{k-1} + b_k + b_{k-1} */
                seq_t term1 = (k >= 1) ? u_prev[k - 1] : (seq_t)0;
                seq_t term2 = (k >= 1) ? v_prev[k - 1] : (seq_t)0;
                seq_t term3 = (k + 1 < r) ? v_prev[k] : (seq_t)0;
                u_new[k] = term1 + term2 + term3;

                /* v_new[0] = 1;  v_new[k] = a_{k-1} + 2*b_{k-1} for k≥1 */
                if (k == 0)
                    v_new[0] = (seq_t)1;
                else
                    v_new[k] = u_prev[k - 1] + (seq_t)2 * v_prev[k - 1];
            }
        }

        u_rows[r] = u_new;
        v_rows[r] = v_new;
    }

    max_row = target;
}

/* Public entry point.  Returns the n-th term of A209759. */
seq_t a(idx_t n)
{
    if (n == 0)                     /* Offset is 1; undefined for n=0. */
        return (seq_t)0;

    /* Find the row r containing the n-th term. */
    idx_t r = 1;
    while ((r * (r + 1) / 2) < n)
        ++r;

    compute_rows_up_to(r);

    /* Compute zero‑based column index k within the row. */
    idx_t prev_sum = (r - 1) * r / 2;   /* number of terms before row r */
    idx_t k = n - prev_sum - 1;         /* 0‑based index in row r */

    return u_rows[r][k];
}
